// Batches answers every batch the sidecar wrote, in write order.
func (p *proxyStore) Batches() []*storev1.WriteBatchRequest {
	p.mu.Lock()
	defer p.mu.Unlock()
	return append([]*storev1.WriteBatchRequest(nil), p.batches...)
}

// mockIngest is one generated tree, ingested.
type mockIngest struct {
	Tree    *mockTree
	Store   *realStore
	Proxy   *proxyStore
	Sidecar *sidecarProc
}

// Entries answers every StoreEntry the sidecar wrote for this tree, in write
// order — the wire view the residue assertions need.
func (in *mockIngest) Entries() []*storev1.StoreEntry {
	return entriesOf(in.Proxy.Batches())
}

// ingestMock starts the real store and the real sidecar over a generated tree
// and waits until every discovered file's cursor has reached its end — the
// signal that ingestion is COMPLETE, so an assertion of "zero residue" is a
// statement about the whole tree and not about however much had landed.
func ingestMock(t *testing.T, tree *mockTree) *mockIngest {
	t.Helper()
	store := startRealStore(t)
	proxy := startProxyStore(t, store.Socket)
	opts := sidecarOptions{
		StoreSocket:        proxy.Socket,
		ConfigRoots:        []string{tree.ConfigRoot},
		SpoolRoot:          tree.SpoolRoot,
		LogPath:            filepath.Join(t.TempDir(), "sidecar.log"),
		PollInterval:       50 * time.Millisecond,
		RescanEvery:        200 * time.Millisecond,
		UnownedSpoolWindow: 200 * time.Millisecond,
	}
	proc := startSidecar(t, opts)
	in := &mockIngest{Tree: tree, Store: store, Proxy: proxy, Sidecar: proc}
	in.awaitDrained(t)
	return in
}

// awaitDrained blocks until the store's cursor for every generated file names
// at least that file's size. The cursor is the sidecar's OWN statement of what
// it has committed, so it is the only honest completion signal available.
func (in *mockIngest) awaitDrained(t *testing.T) {
	t.Helper()
	ctx, cancel := testContext(t)
	defer cancel()
	var files []string
	files = append(files, in.Tree.Transcripts...)
	files = append(files, in.Tree.Subagents...)
	files = append(files, in.Tree.Spools...)
	for _, path := range files {
		info, err := os.Stat(path)
		if err != nil {
			t.Fatalf("stat generated file %s: %v", path, err)
		}
		if info.Size() == 0 {
			continue
		}
		awaitCursorAtLeast(ctx, t, in.Store.Client, resolved(path), info.Size())
	}
}

// Entries answers every StoreEntry the store now holds for one agent's book,
// read back through the store's own read verb.
func (in *mockIngest) BookLines(t *testing.T, agent string) []*storev1.StoreLineAt {
	t.Helper()
	ctx, cancel := testContext(t)
	defer cancel()
	return bookLines(ctx, t, in.Store.Client, agent, 500)
}

// mockLogTail answers the last few records of the mocked vendor's own log —
// the evidence a drive failure needs, quoted into the failure rather than left
// in a file the reader has to go find.
func mockLogTail(path string) string {
	raw, err := os.ReadFile(path)
	if err != nil {
		return fmt.Sprintf("(the mocked vendor's log at %s could not be read: %v)", path, err)
	}
	lines := strings.Split(strings.TrimRight(string(raw), "\n"), "\n")
	if len(lines) > 12 {
		lines = lines[len(lines)-12:]
	}
	return strings.Join(lines, "\n")
}
